// Ingest alert from Departmental Agent
const inputData = $input.first().json;
const timestamp = new Date().toISOString();

const alertPayload = {
  command_alert_id: 'CMD-' + Date.now(),
  source_agent: inputData.source_agent || 'departmental_agent',
  incident_reference_id: inputData.incident_id || inputData.reading_id || inputData.complaint_id || 'INC-UNKNOWN',
  priority: inputData.risk_level || inputData.severity_level || inputData.severity || inputData.priority || 'HIGH',
  headline: inputData.command_alert_headline || inputData.headline || 'Departmental Alert Received',
  received_at: timestamp,
  raw_payload: inputData
};

// Decision Logic: Determine Unified Action Tasks
const unifiedTask = {
  task_id: 'UTASK-' + Math.random().toString(36).substring(2, 9).toUpperCase(),
  assigned_agency: alertPayload.source_agent.toUpperCase().replace('_', ' ') + ' FIELD UNIT',
  priority: alertPayload.priority,
  status: 'QUEUED_FOR_EXECUTION',
  authority_approval_required: alertPayload.priority === 'CRITICAL' || alertPayload.priority === 'SEVERE',
  created_at: timestamp
};

return {
  success: true,
  status: 'COORDINATED_BY_CITY_COMMAND',
  alert: alertPayload,
  unified_task: unifiedTask,
  timestamp: timestamp
};
